begin;
create index products_status_archived_idx on public.products(status,archived_at);create index products_brand_category_idx on public.products(brand_id,category_id);create index product_images_product_order_idx on public.product_images(product_id,display_order) where is_active;create unique index product_single_cover_idx on public.product_images(product_id) where image_role='cover' and is_active;create index inquiries_status_created_idx on public.inquiries(status,created_at desc);create index inquiries_email_ci_idx on public.inquiries(lower(email::text));create index customers_status_activity_idx on public.customers(status,last_activity_at desc);create index timeline_customer_created_idx on public.customer_timeline(customer_id,created_at desc);create index audit_actor_created_idx on public.admin_audit_log(actor_id,created_at desc);create index import_jobs_status_started_idx on public.import_jobs(status,started_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
do $$declare table_name text;begin foreach table_name in array array['profiles','brands','categories','products','product_specifications','product_images','inquiries','customers','customer_notes','collection_settings'] loop execute format('create trigger set_%I_updated_at before update on public.%I for each row execute function public.set_updated_at()',table_name,table_name);end loop;end$$;
create or replace function public.record_product_status_change() returns trigger language plpgsql security definer set search_path='' as $$begin if old.status is distinct from new.status then insert into public.product_status_history(product_id,from_status,to_status,changed_by) values(new.id,old.status,new.status,auth.uid());end if;return new;end$$;
create trigger product_status_audit after update of status on public.products for each row execute function public.record_product_status_change();
revoke all on function public.record_product_status_change() from public;revoke all on function public.set_updated_at() from public;
commit;
